export type TransportCallback = (data: TransportData) => void;
export type MidiMessageCallback = (status: number, data1: number, data2: number) => void;

// Global augmentations for bridge detection
declare global {
    interface Window {
        electronMidi?: {
            send: (channel: string, ...args: any[]) => void;
            receive?: (channel: string, func: Function) => void;
        };
        vstMidi?: {
            sendMidi: (bytes: number[]) => void;
        };
    }
}

export interface IHostAdapter {
    type: 'web' | 'electron' | 'vst';
    init(): Promise<boolean>;
    getOutputs(): Promise<MidiDevice[]>;
    setOutput(id: string | null): void;
    sendMidi(bytes: number[]): void;
    setTransportCallback(cb: TransportCallback | null): void;
    setInputCallback(cb: MidiMessageCallback | null): void;
}

/**
 * Standard Web MIDI Implementation
 */
export class WebHostAdapter implements IHostAdapter {
    type = 'web' as const;
    private access: any = null;
    private output: any = null;
    private inputCallback: MidiMessageCallback | null = null;

    async init(): Promise<boolean> {
        if ((navigator as any).requestMIDIAccess) {
            try {
                this.access = await (navigator as any).requestMIDIAccess();
                this.setupInputs();

                // Handle hot-plugging
                this.access.onstatechange = (e: any) => {
                    if (e.port.type === 'input' && e.port.state === 'connected') {
                        this.setupInputs();
                    }
                };
                return true;
            } catch (e) {
                console.error("Web MIDI Access Refused", e);
                return false;
            }
        }
        return false;
    }

    private setupInputs() {
        if (!this.access) return;
        this.access.inputs.forEach((input: any) => {
            // Avoid re-binding if already bound (though simple reassignment is safe)
            input.onmidimessage = (e: any) => {
                if (this.inputCallback && e.data.length >= 2) {
                    // Normalize data: Status, Data1, Data2 (0 if not present)
                    const d2 = e.data.length > 2 ? e.data[2] : 0;
                    this.inputCallback(e.data[0], e.data[1], d2);
                }
            };
        });
    }

    async getOutputs(): Promise<MidiDevice[]> {
        if (!this.access) return [];
        const devices: MidiDevice[] = [];
        this.access.outputs.forEach((output: any) => {
            devices.push({ id: output.id, name: output.name || `Output ${output.id}` });
        });
        return devices;
    }

    setOutput(id: string | null) {
        if (this.access && id) {
            this.output = this.access.outputs.get(id) || null;
        } else {
            this.output = null;
        }
    }

    sendMidi(bytes: number[]) {
        if (this.output) {
            this.output.send(bytes);
        }
    }

    setTransportCallback(cb: TransportCallback | null) {
        // Web MIDI doesn't strictly have a transport standard without WebMIDI Clock parsing.
        // Future implementation could parse MIDI Clock messages here.
    }

    setInputCallback(cb: MidiMessageCallback | null) {
        this.inputCallback = cb;
        // Re-bind existing inputs to the new callback
        this.setupInputs();
    }
}

/**
 * Electron IPC Bridge Implementation
 */
export class ElectronHostAdapter implements IHostAdapter {
    type = 'electron' as const;

    async init(): Promise<boolean> {
        return !!window.electronMidi;
    }

    async getOutputs(): Promise<MidiDevice[]> {
        return [{ id: 'virtual', name: 'PrismaTonal Virtual Output' }];
    }

    setOutput(id: string | null) {
        // Electron bridge typically routes to a virtual port managed by the main process
    }

    sendMidi(bytes: number[]) {
        if (window.electronMidi) {
            window.electronMidi.send('midi-message', bytes);
        }
    }

    setTransportCallback(cb: TransportCallback | null) {
        if (window.electronMidi && window.electronMidi.receive && cb) {
            window.electronMidi.receive('transport-update', (_: any, data: TransportData) => {
                cb(data);
            });
        }
    }

    setInputCallback(cb: MidiMessageCallback | null) {
        if (window.electronMidi && window.electronMidi.receive && cb) {
            window.electronMidi.receive('midi-input', (_: any, bytes: number[]) => {
               if (bytes.length >= 2) {
                   const d2 = bytes.length > 2 ? bytes[2] : 0;
                   cb(bytes[0], bytes[1], d2);
               }
            });
        }
    }
}

/**
 * VST/Plugin WebView Bridge Implementation
 */
export class VSTHostAdapter implements IHostAdapter {
    type = 'vst' as const;

    async init(): Promise<boolean> {
        return !!window.vstMidi;
    }

    async getOutputs(): Promise<MidiDevice[]> {
        return [{ id: 'host', name: 'DAW Host Track' }];
    }

    setOutput(id: string | null) {
        // Always routes to host track
    }

    sendMidi(bytes: number[]) {
        if (window.vstMidi) {
            window.vstMidi.sendMidi(bytes);
        }
    }

    setTransportCallback(cb: TransportCallback | null) {
        // VST Bridge placeholder
    }

    setInputCallback(cb: MidiMessageCallback | null) {
        // VST Bridge placeholder for inbound MIDI
        // e.g. window.onMidiMessage = ...
    }
}

/**
 * Factory to detect and instantiate the correct adapter
 */
export const createHostAdapter = async (): Promise<IHostAdapter | null> => {
    // 1. Electron
    if (window.electronMidi) {
        const adapter = new ElectronHostAdapter();
        await adapter.init();
        return adapter;
    }
    // 2. VST
    if (window.vstMidi) {
        const adapter = new VSTHostAdapter();
        await adapter.init();
        return adapter;
    }
    // 3. Web
    if ((navigator as any).requestMIDIAccess) {
        const adapter = new WebHostAdapter();
        if (await adapter.init()) {
            return adapter;
        }
    }
    return null;
}

import { createHostAdapter, IHostAdapter, MidiDevice, TransportCallback } from './HostAdapter';

// Re-export for consumers (SettingsModal, etc.)
export type { MidiDevice };

type SustainListener = (active: boolean) => void;

class MidiService {
    private adapter: IHostAdapter | null = null;
    private initialized = false;

    // Channel Management for Polyphonic Pitch Bend (MPE-style)
    private activeNotes: Map<string, { channel: number, note: number }> = new Map(); 
    private nextChannel = 0; // 0-15 (corresponding to Ch 1-16)

    private sustainListeners: Set<SustainListener> = new Set();

    constructor() {}

    public async init(): Promise<boolean> {
        if (this.initialized) return true;

        this.adapter = await createHostAdapter();

        if (this.adapter) {
            console.log(`Initializing MIDI: ${this.adapter.type.toUpperCase()} Backend Detected`);
            this.initialized = true;

            // Set up input listening
            this.adapter.setInputCallback((status, d1, d2) => {
                this.handleIncomingMidi(status, d1, d2);
            });

            return true;
        } else {
            console.warn("MIDI not supported in this environment");
            return false;
        }
    }

    private handleIncomingMidi(status: number, d1: number, d2: number) {
        const channel = status & 0x0F;
        const type = status & 0xF0;

        // Control Change (0xB0)
        if (type === 0xB0) {
            // CC 64: Sustain Pedal
            if (d1 === 64) {
                const isActive = d2 >= 64;
                this.notifySustainListeners(isActive);
            }
        }
    }

    public onSustain(cb: SustainListener) {
        this.sustainListeners.add(cb);
        return () => { this.sustainListeners.delete(cb); };
    }

    private notifySustainListeners(active: boolean) {
        this.sustainListeners.forEach(cb => cb(active));
    }

    public async getOutputs(): Promise<MidiDevice[]> {
        if (!this.adapter) return [];
        return this.adapter.getOutputs();
    }

    public setOutput(id: string | null) {
        if (this.adapter) {
            this.adapter.setOutput(id);
        }
    }

    public setTransportCallback(cb: TransportCallback) {
        if (this.adapter) {
            this.adapter.setTransportCallback(cb);
        }
    }

    // --- MIDI MESSAGES ---

    private sendBytes(bytes: number[]) {
        if (this.adapter) {
            this.adapter.sendMidi(bytes);
        }
    }

    public sendControlChange(cc: number, value: number, channel: number = 0) {
        this.sendBytes([0xB0 | channel, cc, value]);
    }

    public sendSustain(active: boolean) {
        const val = active ? 127 : 0;
        // In MPE mode, it's safest to send Sustain to ALL channels to ensure voices on rotated channels hold.
        // Some synths only listen to Ch 1, but MPE specs usually treat CCs on Ch 1 as "Common" 
        // or require per-channel redundancy. We'll do redundancy to be safe.
        for (let ch = 0; ch < 16; ch++) {
            this.sendControlChange(64, val, ch);
        }
    }

    public noteOn(id: string, ratio: number, baseFreq: number, bendRange: number) {
        const freq = baseFreq * ratio;
        const midiFloat = 69 + 12 * Math.log2(freq / 440);
        const noteNumber = Math.round(midiFloat);
        const bendSemitones = midiFloat - noteNumber;

        const normalizedBend = bendSemitones / bendRange; 
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        // Channel Rotation for MPE
        let channel = this.nextChannel;
        this.nextChannel = (this.nextChannel + 1) % 16; 

        this.activeNotes.set(id, { channel, note: noteNumber });

        // Pitch Bend LSB/MSB
        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;

        // Send Pitch Bend (0xE0)
        this.sendBytes([0xE0 | channel, lsb, msb]);

        // Send Note On (0x90)
        this.sendBytes([0x90 | channel, noteNumber, 100]);
    }

    public noteOff(id: string) {
        const data = this.activeNotes.get(id);
        if (!data) return;

        // Note Off (0x80)
        this.sendBytes([0x80 | data.channel, data.note, 0]);
        this.activeNotes.delete(id);
    }

    public pitchBend(id: string, ratio: number, baseFreq: number, bendRange: number) {
        const data = this.activeNotes.get(id);
        if (!data) return;

        // Re-calc logic
        const freq = baseFreq * ratio;
        const exactMidi = 69 + 12 * Math.log2(freq / 440);

        const diffSemitones = exactMidi - data.note;

        const normalizedBend = diffSemitones / bendRange;
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;

        this.sendBytes([0xE0 | data.channel, lsb, msb]);
    }

    // Standard MIDI Panic: Sends All Notes Off (CC 123) and All Sound Off (CC 120) to all channels
    public panic() {
        this.activeNotes.clear();
        if (!this.adapter) return;

        for (let ch = 0; ch < 16; ch++) {
            // CC 123: All Notes Off
            this.sendBytes([0xB0 | ch, 123, 0]);
            // CC 120: All Sound Off (Immediate mute)
            this.sendBytes([0xB0 | ch, 120, 0]);
            // Reset Pitch Bend
            this.sendBytes([0xE0 | ch, 0, 64]);
            // Reset Sustain
            this.sendBytes([0xB0 | ch, 64, 0]);
        }
    }
}

