          >
            Plucked
          </button>

          {/* Empty Placeholders - Adjusted count */}
          {!isShortScreen && [1,2].map(i => (
              <button 
                key={i}
                disabled
                className="rounded-lg border-2 border-slate-800 bg-slate-900/30 text-slate-700 flex items-center justify-center pointer-events-none"
