                    width: '350px', 
                    height: '320px', 
                    minWidth: '350px',
                    minHeight: '200px',
                    maxWidth: 'calc(100vw - 40px)',
                    maxHeight: '90vh',
                    resize: 'both',
                    overflow: 'hidden' 
                }}
