import { audioEngine } from './AudioEngine';

export type RecordingMode = 'video-audio' | 'audio-only';

class RecordingService {
    private mediaRecorder: MediaRecorder | null = null;
    private recordedChunks: Blob[] = [];
    private stream: MediaStream | null = null;
    private audioDest: MediaStreamAudioDestinationNode | null = null;

    public isRecording: boolean = false;

    constructor() {}

    /**
     * Start recording based on the selected mode.
     * @param mode 'video-audio' uses getDisplayMedia, 'audio-only' uses WebAudio API
     * @returns Promise that resolves when recording successfully starts
     */
    public async startRecording(mode: RecordingMode): Promise<void> {
        this.recordedChunks = [];
        this.isRecording = true;

        try {
            if (mode === 'video-audio') {
                await this.startScreenCapture();
            } else {
                await this.startAudioCapture();
            }
        } catch (error) {
            console.error("Failed to start recording:", error);
            this.isRecording = false;
            throw error;
        }
    }

    private async startScreenCapture() {
        // "Hardware capture" for Audio+Visual
        // This prompts the user to share a tab or screen.
        // Important: User must select "Share Audio" in the browser dialog for system audio to be captured.
        const displayStream = await navigator.mediaDevices.getDisplayMedia({
            video: {
                displaySurface: "browser", // Prefer tab sharing
            } as MediaTrackConstraints, 
            audio: {
                echoCancellation: false,
                noiseSuppression: false,
                autoGainControl: false
            }
        });

        this.stream = displayStream;
        this.setupMediaRecorder(this.stream, 'video/webm;codecs=vp9,opus');
    }

    private async startAudioCapture() {
        // "Hardware capture" equivalent for Audio Only
        // Creates a virtual destination node in the Web Audio graph
        const ctx = audioEngine.getContext();
        if (!ctx) {
            // Ensure audio is initialized
            await audioEngine.init();
        }

        const context = audioEngine.getContext();
        if (!context) throw new Error("Audio Context not available");

        this.audioDest = context.createMediaStreamDestination();
        audioEngine.connectToRecordingDestination(this.audioDest);

        this.stream = this.audioDest.stream;
        this.setupMediaRecorder(this.stream, 'audio/webm;codecs=opus');
    }

    private setupMediaRecorder(stream: MediaStream, mimeTypePreference: string) {
        // Check supported types
        let mimeType = mimeTypePreference;
        if (!MediaRecorder.isTypeSupported(mimeType)) {
            // Fallback
            if (mimeType.startsWith('video')) {
                mimeType = 'video/mp4';
                if (!MediaRecorder.isTypeSupported(mimeType)) mimeType = 'video/webm';
            } else {
                mimeType = 'audio/mp4';
                if (!MediaRecorder.isTypeSupported(mimeType)) mimeType = 'audio/webm'; 
            }
        }

        this.mediaRecorder = new MediaRecorder(stream, { mimeType });

        this.mediaRecorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
                this.recordedChunks.push(event.data);
            }
        };

        this.mediaRecorder.onstop = () => {
            this.finalizeRecording();
        };

        // If the user stops sharing via the browser UI, stop the recorder
        stream.getVideoTracks().forEach(track => {
            track.onended = () => {
                if (this.isRecording) this.stopRecording();
            };
        });

        this.mediaRecorder.start(100); // Collect chunks every 100ms
    }

    public stopRecording() {
        if (this.mediaRecorder && this.isRecording) {
            this.mediaRecorder.stop();
            this.isRecording = false;
        }

        // Stop all tracks to release hardware/indicator
        if (this.stream) {
            this.stream.getTracks().forEach(track => track.stop());
        }

        // Disconnect audio node if used
        if (this.audioDest) {
            this.audioDest.disconnect();
            this.audioDest = null;
        }
    }

    private finalizeRecording() {
        if (this.recordedChunks.length === 0) return;

        const blob = new Blob(this.recordedChunks, {
            type: this.mediaRecorder?.mimeType || 'video/webm'
        });

        const isVideo = blob.type.startsWith('video');
        const ext = isVideo ? 'webm' : 'webm'; // Browser MediaRecorder mostly outputs webm containers
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const filename = `PrismaTonal_Performance_${timestamp}.${ext}`;

        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        document.body.appendChild(a);
        a.style.display = 'none';
        a.href = url;
        a.download = filename;
        a.click();

        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
    }
}

export const recordingService = new RecordingService();

import React, { useState, useEffect, useRef } from 'react';
import { recordingService, RecordingMode } from '../services/RecordingService';

const RecordingControls: React.FC = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [mode, setMode] = useState<RecordingMode>('video-audio');
  const [duration, setDuration] = useState(0);
  const [isExpanded, setIsExpanded] = useState(false);
  const timerRef = useRef<number | null>(null);
  const syncTimerRef = useRef<number | null>(null);

  // Format seconds to MM:SS
  const formatTime = (secs: number) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const handleToggleRecord = async () => {
    if (isRecording) {
      handleStop();
    } else {
      try {
        await recordingService.startRecording(mode);
        setIsRecording(true);
        setDuration(0);

        // Start Duration Timer
        timerRef.current = window.setInterval(() => {
          setDuration(prev => prev + 1);
        }, 1000);

        // Start Safety Sync Timer (checks if browser stopped sharing externally)
        syncTimerRef.current = window.setInterval(() => {
            if (!recordingService.isRecording) {
                handleStop();
            }
        }, 1000);

      } catch (e) {
        alert("Failed to start recording. Please ensure permissions are granted.");
        console.error(e);
      }
    }
  };

  const handleStop = () => {
    recordingService.stopRecording();
    setIsRecording(false);

    if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
    }
    if (syncTimerRef.current) {
        clearInterval(syncTimerRef.current);
        syncTimerRef.current = null;
    }
  };

  // Cleanup on unmount
  useEffect(() => {
      return () => {
          if (timerRef.current) clearInterval(timerRef.current);
          if (syncTimerRef.current) clearInterval(syncTimerRef.current);
      };
  }, []);

  return (
    <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-[160] transition-all duration-300 ${isRecording ? 'opacity-100' : 'opacity-80 hover:opacity-100'}`}>
        <div className={`bg-slate-900/80 backdrop-blur-md border border-slate-700 rounded-full shadow-2xl flex items-center overflow-hidden transition-all ${isExpanded || isRecording ? 'px-1 py-1 pr-4' : 'px-1 py-1'}`}>

            {/* Collapse/Expand Toggle (Implicit via mode selection visibility) */}

            <div className={`flex items-center gap-1 overflow-hidden transition-all duration-300 ${isExpanded && !isRecording ? 'w-auto opacity-100 mr-2' : 'w-0 opacity-0'}`}>
                <button 
                    onClick={() => setMode('video-audio')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase whitespace-nowrap transition-colors ${mode === 'video-audio' ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor"><path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z" /></svg>
                    Screen
                </button>
                <button 
                    onClick={() => setMode('audio-only')}
                    className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase whitespace-nowrap transition-colors ${mode === 'audio-only' ? 'bg-purple-600 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'}`}
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9.383 3.076A1 1 0 0110 4v12a1 1 0 01-1.707.707L4.586 13H2a1 1 0 01-1-1V8a1 1 0 011-1h2.586l3.707-3.707a1 1 0 011.09-.217zM14.657 2.929a1 1 0 011.414 0A9.972 9.972 0 0119 10a9.972 9.972 0 01-2.929 7.071 1 1 0 01-1.414-1.414A7.971 7.971 0 0017 10c0-2.21-.894-4.208-2.343-5.657a1 1 0 010-1.414zm-2.829 2.828a1 1 0 011.415 0A5.983 5.983 0 0115 10a5.983 5.983 0 01-1.757 4.243 1 1 0 01-1.415-1.415A3.984 3.984 0 0013 10a3.983 3.983 0 00-1.172-2.828 1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                    Audio
                </button>
            </div>

            <button 
                onClick={handleToggleRecord}
                onMouseEnter={() => !isRecording && setIsExpanded(true)}
                className={`relative flex items-center justify-center rounded-full transition-all duration-300 group ${isRecording ? 'w-8 h-8 bg-slate-800' : 'w-10 h-10 bg-red-600 hover:bg-red-500 hover:scale-105'}`}
            >
                {isRecording ? (
                    <div className="w-3 h-3 bg-red-500 rounded-sm animate-pulse shadow-[0_0_10px_red]"></div>
                ) : (
                    <div className={`rounded-full bg-white transition-all duration-300 ${isExpanded ? 'w-3 h-3' : 'w-4 h-4'}`}></div>
                )}
            </button>

            {isRecording && (
                <div className="flex flex-col ml-3 mr-1">
                    <span className="text-[10px] font-mono font-bold text-red-400 animate-pulse leading-none tracking-wider mb-0.5">REC</span>
                    <span className="text-xs font-mono font-bold text-white leading-none">{formatTime(duration)}</span>
                </div>
            )}

            {/* Label when expanded but not recording */}
            {isExpanded && !isRecording && (
                <div className="ml-2 flex flex-col justify-center" onMouseLeave={() => setIsExpanded(false)}>
                    <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest leading-none">Record</span>
                    <span className="text-[9px] text-slate-500 leading-none mt-0.5">{mode === 'video-audio' ? 'Video + Audio' : 'Audio Only'}</span>
                </div>
            )}
        </div>
    </div>
  );
};

