                    <div className="flex gap-2">
                        {onPlayAll && (
                            <button 
                                className="text-[10px] font-bold bg-green-900/50 hover:bg-green-700 text-green-400 hover:text-white px-2 py-0.5 rounded border border-green-700 transition-colors"
                                onPointerDown={(e) => { e.stopPropagation(); onPlayAll(); }}
                            >
                                PLAY ALL
                            </button>
                        )}
                        {onStopAll && (
                            <button 
                                className="text-[10px] font-bold bg-red-900/50 hover:bg-red-700 text-red-400 hover:text-white px-2 py-0.5 rounded border border-red-700 transition-colors"
                                onPointerDown={(e) => { e.stopPropagation(); onStopAll(); }}
                            >
                                STOP ALL
                            </button>
                        )}
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto overflow-x-hidden bg-slate-900/30 rounded-lg border border-slate-800 seq-scroll p-1 min-h-0">
                    {arpeggios.map((arp) => {
                        const isPlaying = arp.isPlaying;
                        const config = arp.config || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8 };
                        const patternLength = config.length;

                        const steps = Array.from({ length: patternLength }, (_, i) => {
                            if (arp.steps.length > i) return arp.steps[i]; 
                            return null;
                        });

                        return (
                            <div key={arp.id} className="flex flex-col mb-2 bg-slate-800/20 rounded border border-white/5 hover:border-white/10 transition-colors">
                                <div className="flex items-center gap-2 p-1 border-b border-white/5 bg-slate-800/40 rounded-t">
                                    <button 
                                        className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold border ${isPlaying ? 'bg-blue-600 border-blue-400 text-white' : 'bg-slate-700 border-slate-600 text-slate-400 hover:text-white'}`}
                                        onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                                    >
                                        {arp.id}
                                    </button>

                                    <div className="flex items-center gap-1 bg-slate-900/50 rounded px-1 border border-slate-700/50">
                                        <span className="text-[8px] font-bold text-slate-500 uppercase">Len</span>
                                        <button className="text-[10px] text-slate-400 hover:text-white" onPointerDown={(e) => {e.stopPropagation(); onArpRowConfigChange && onArpRowConfigChange(arp.id, {length: Math.max(1, config.length - 1)})}}>-</button>
                                        <span className="text-[9px] font-mono w-3 text-center text-slate-300">{config.length}</span>
                                        <button className="text-[10px] text-slate-400 hover:text-white" onPointerDown={(e) => {e.stopPropagation(); onArpRowConfigChange && onArpRowConfigChange(arp.id, {length: Math.min(32, config.length + 1)})}}>+</button>
                                    </div>

                                    <div className="flex items-center gap-1 bg-slate-900/50 rounded px-1 border border-slate-700/50">
                                        <span className="text-[8px] font-bold text-slate-500 uppercase">Div</span>
                                        <select 
                                            value={config.division}
                                            onChange={(e) => onArpRowConfigChange && onArpRowConfigChange(arp.id, { division: e.target.value as ArpDivision })}
                                            className="h-4 text-[9px] bg-transparent text-slate-300 font-mono focus:outline-none cursor-pointer"
                                        >
                                            {(['1/1', '1/2', '1/4', '1/8', '1/16', '1/32', '1/4T', '1/8T', '1/16T'] as ArpDivision[]).map(div => (
                                                <option key={div} value={div}>{div}</option>
                                            ))}
                                        </select>
                                    </div>

                                    <div className="flex items-center gap-1 bg-slate-900/50 rounded px-1 border border-slate-700/50">
                                        <span className="text-[8px] font-bold text-slate-500 uppercase">Gate</span>
                                        <button className="text-[10px] text-slate-400 hover:text-white" onPointerDown={(e) => {e.stopPropagation(); onArpRowConfigChange && onArpRowConfigChange(arp.id, {gate: Math.max(0.1, config.gate - 0.1)})}}>-</button>
                                        <span className="text-[9px] font-mono w-5 text-center text-slate-300">{(config.gate*100).toFixed(0)}</span>
                                        <button className="text-[10px] text-slate-400 hover:text-white" onPointerDown={(e) => {e.stopPropagation(); onArpRowConfigChange && onArpRowConfigChange(arp.id, {gate: Math.min(1.0, config.gate + 0.1)})}}>+</button>
                                    </div>

                                    <div className="flex-1"></div>

                                    <button
                                        className="text-[10px] text-slate-600 hover:text-red-400 transition-colors"
                                        title="Clear Pattern"
                                        onPointerDown={(e) => { e.stopPropagation(); handleClearPattern && handleClearPattern(arp.id); }}
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor">
                                            <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                                        </svg>
                                    </button>
                                </div>

                                <div className="flex gap-1 overflow-x-auto seq-scroll p-1 items-center h-10 w-full">
                                    {steps.map((step, idx) => {
                                        const isCurrent = isPlaying && idx === (currentArpStep || 0) % patternLength;
                                        const hasData = step !== null;
                                        const isMuted = step?.muted;

                                        const borderColor = hasData ? 'border-blue-500' : 'border-slate-700';
                                        const bgColor = isCurrent ? 'bg-slate-600' : (hasData && isMuted ? 'bg-slate-900' : 'bg-slate-800/80');
                                        const textColor = hasData ? (isMuted ? 'text-slate-600' : 'text-blue-200') : 'text-slate-600';

                                        const limitN = hasData ? getMaxPrime(step.n || 1) : 1;
                                        const limitD = hasData ? getMaxPrime(step.d || 1) : 1;

                                        const colorN = DEFAULT_COLORS[limitN as keyof typeof DEFAULT_COLORS] || '#fff';
                                        const colorD = DEFAULT_COLORS[limitD as keyof typeof DEFAULT_COLORS] || '#fff';

                                        const squareStyle = hasData ? {
                                            background: `linear-gradient(135deg, ${colorN} 50%, ${colorD} 50%)`
                                        } : {};

                                        return (
                                            <div 
                                                key={idx} 
                                                className={`flex-shrink-0 w-8 h-8 rounded border flex items-center justify-center transition-all m-0.5 cursor-pointer relative overflow-hidden
                                                    ${!hasData ? bgColor : ''} ${borderColor} ${isCurrent ? 'shadow-lg scale-110 z-10 border-white' : ''} 
                                                    ${hasData ? 'hover:border-white' : ''}
                                                `}
                                                style={squareStyle}
                                                title={hasData ? `Ratio: ${step?.n}/${step?.d} (Left: Toggle Mute, Right: Delete)` : `Step ${idx+1}`}
                                                onPointerDown={(e) => e.stopPropagation()} 
                                                onClick={(e) => hasData && handleStepClick(e, arp.id, idx)}
                                                onContextMenu={(e) => hasData && handleStepRightClick(e, arp.id, idx)}
                                            >
                                                {hasData ? (
                                                    <div className={`w-full h-full relative ${isMuted ? 'opacity-30 grayscale' : ''}`}>
                                                        <span className="absolute top-0.5 left-1 text-[9px] font-bold text-white leading-none drop-shadow-md shadow-black">
                                                            {step?.n}
                                                        </span>
                                                        <span className="absolute bottom-0.5 right-1 text-[9px] font-bold text-white leading-none drop-shadow-md shadow-black">
                                                            {step?.d}
                                                        </span>
                                                    </div>
                                                ) : (
                                                    <span className={`text-[10px] font-mono ${textColor} select-none`}>{idx+1}</span>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="flex justify-between items-center relative mt-1 flex-shrink-0">
                     <div className="flex items-center gap-2">
                         {recordingArpId && (
                             <span className="text-[10px] text-red-400 animate-pulse">Rec: {recordingArpId}</span>
                         )}
                     </div>

                     <div className="flex items-center gap-2">
                         {/* Integrated Recording Button */}
                         <button 
                            onClick={handleToggleRecord}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded text-[10px] font-bold uppercase tracking-wider transition-all border ${isRecording ? 'bg-red-900/80 border-red-500 text-white animate-pulse' : 'bg-slate-800 hover:bg-slate-700 border-slate-600 text-slate-300'}`}
                         >
                             <div className={`w-2 h-2 rounded-full ${isRecording ? 'bg-red-500' : 'bg-red-500/70'}`}></div>
                             {isRecording ? `REC ${formatRecTime(recDuration)}` : 'Record Audio'}
                         </button>
                     </div>
                </div>
            </div>
        )}
      </div>

      {/* NEW LEFT INSTRUMENTS CLUSTER */}
      <div 
        className={`absolute flex flex-col gap-4 z-[140] bg-slate-900/50 p-3 rounded-xl backdrop-blur-sm border border-slate-700/50 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('instruments') }}
        onPointerDown={(e) => handleDrag(e, 'instruments')}
      >
          {/* Drone Button + Volume */}
          <div className="flex items-center gap-3">
              <VolumeWheel 
                  value={presets?.latch.gain || 0.5} 
                  onChange={(v) => updatePatchGain('latch', v)} 
                  color="#22c55e" 
                  width={wheelWidth} 
                  height={instrButtonSize} 
                  uiScale={uiScale}
              />
              <button 
                className={`rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-[10px] uppercase tracking-wider ${latchMode === 1 ? 'bg-green-600 border-green-400 text-white shadow-[0_0_10px_rgba(34,197,94,0.5)]' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'} ${hasDroneAura ? droneAuraClass : ''}`}
                style={{ width: instrButtonSize, height: instrButtonSize, fontSize: 15 * uiScale }}
                onPointerDown={(e) => !uiUnlocked && handleButtonPress(e, 'instruments', onLatch)}
                onContextMenu={(e) => { e.preventDefault(); if(!uiUnlocked && onClearSustain) onClearSustain(1); }}
              >
                Drone
              </button>
          </div>

          {/* Strings Button + Volume */}
          <div className="flex items-center gap-3">
              <VolumeWheel 
                  value={presets?.normal.gain || 0.5} 
                  onChange={(v) => updatePatchGain('normal', v)} 
                  color="#3b82f6" 
                  width={wheelWidth} 
                  height={instrButtonSize} 
                  uiScale={uiScale}
              />
              <button 
                className={`rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-[10px] uppercase tracking-wider ${latchMode === 2 ? 'bg-blue-600 border-blue-400 text-white shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'} ${hasStringsAura ? stringsAuraClass : ''}`}
                style={{ width: instrButtonSize, height: instrButtonSize, fontSize: 15 * uiScale }}
                onPointerDown={(e) => onSust && !uiUnlocked && handleButtonPress(e, 'instruments', onSust)}
                onContextMenu={(e) => { e.preventDefault(); if(!uiUnlocked && onClearSustain) onClearSustain(2); }}
              >
                Strings
              </button>
          </div>

          {/* Plucked Button + Volume */}
          <div className="flex items-center gap-3">
              <VolumeWheel 
                  value={presets?.strum.gain || 0.5} 
                  onChange={(v) => updatePatchGain('strum', v)} 
                  color="#f97316" 
                  width={wheelWidth} 
                  height={instrButtonSize} 
                  uiScale={uiScale}
              />
              <button 
                className={`rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-[10px] uppercase tracking-wider ${latchMode === 3 ? 'bg-orange-600 border-orange-400 text-white shadow-[0_0_10px_rgba(249,115,22,0.5)]' : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-500'} ${latchMode === 3 ? '' : ''}`}
                style={{ width: instrButtonSize, height: instrButtonSize, fontSize: 15 * uiScale }}
                onPointerDown={(e) => onPluck && !uiUnlocked && handleButtonPress(e, 'instruments', onPluck)}
                onContextMenu={(e) => { e.preventDefault(); if(!uiUnlocked && onClearSustain) onClearSustain(3); }}
              >
                Plucked
              </button>
          </div>
      </div>

      {/* BOTTOM RIGHT CLUSTER - Modified */}

      {/* Bend - LOCKED IF PLUCKED OR SUSTAIN ON */}
      <button 
        disabled={isBendLocked}
        className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${isBendEnabled ? 'bg-purple-600 text-white border-purple-300 shadow-[0_0_15px_rgba(168,85,247,0.6)]' : 'bg-purple-900/40 text-purple-400 border-purple-500/50 hover:bg-purple-800/60'} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''} ${isBendLocked ? 'opacity-40 cursor-not-allowed grayscale' : ''}`} 
        style={{ ...draggableStyle('bend'), width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} 
        onPointerDown={(e) => !isBendLocked && handleButtonPress(e, 'bend', onBend)}
      >
        BEND
      </button>

      {/* Sust - LOCKED IF PLUCKED */}
      <button 
        disabled={isSustainLocked}
        className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${sustColorClass} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''} ${isSustainLocked ? 'opacity-40 cursor-not-allowed grayscale' : ''}`} 
        style={{ ...draggableStyle('sust'), width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} 
        onPointerDown={(e) => !isSustainLocked && handleButtonPress(e, 'sust', onSustainToggle)} 
        title="Sustain Notes"
      >
        SUST
      </button>

      <button className={`absolute rounded-full bg-yellow-900/40 border-2 border-yellow-500/50 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-yellow-800/60 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('off'), width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'off', onOff)}>OFF</button>
      <button className={`absolute rounded-full bg-red-900/40 border-2 border-red-500/50 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-800/60 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('panic'), width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'panic', onPanic)}>PANIC</button>

      <button className={`absolute rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold backdrop-blur hover:bg-yellow-600/40 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('center'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'center', onCenter)} title="Center Display"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /></svg></button>

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-blue-500 font-bold backdrop-blur hover:bg-blue-600/40 active:bg-blue-600 active:text-white transition-all shadow-[0_0_15px_rgba(59,130,246,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('depth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'depth', onIncreaseDepth)} title="Increase Depth from Selection"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>)}

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('decreaseDepth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'decreaseDepth', onDecreaseDepth)} title="Decrease Depth"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 12h-15" /></svg></button>)}

      <div className={`absolute flex items-center gap-2 z-[150] transition-all ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50 rounded-lg p-1 border-dashed border-2 border-yellow-500/50' : ''}`} style={{ ...draggableStyle('chords') }} onPointerDown={(e) => handleDrag(e, 'chords')}>
          <button className="rounded bg-indigo-600/20 border-2 border-indigo-500 flex items-center justify-center text-indigo-500 font-bold backdrop-blur hover:bg-indigo-600/40 active:bg-indigo-600 active:text-white transition-all shadow-[0_0_15px_rgba(99,102,241,0.4)] select-none" style={{ width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'chords', onAddChord)} title="Store Current Chord"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>

          {!uiUnlocked && savedChords.filter(c => c.visible).map((chord, i) => {
              const isActive = activeChordIds.includes(chord.id);
              return (
                  <button key={chord.id} className={`rounded border-2 flex items-center justify-center font-bold backdrop-blur transition-all shadow-lg select-none ${isActive ? 'bg-indigo-600 border-indigo-400 text-white shadow-[0_0_15px_rgba(99,102,241,0.8)] scale-110' : 'bg-slate-800/60 border-slate-600 text-slate-400 hover:border-indigo-500 hover:text-indigo-400'}`} style={{ width: chordSize, height: chordSize, fontSize: 14 * uiScale }} onPointerDown={(e) => { e.stopPropagation(); toggleChord(chord.id); }} onContextMenu={(e) => { e.preventDefault(); e.stopPropagation(); if(onRemoveChord) onRemoveChord(chord.id); }}>
                      {chord.label}
                  </button>
              );
          })}
      </div>
    </>
  );
};

export default FloatingControls;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos, ArpeggioStep, ArpConfig, ArpeggioDefinition } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';

const REFERENCE_SHORT_EDGE = 1080; 

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control
  const [viewZoom, setViewZoom] = useState(1.0);

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);

  // Latch Modes: 0=Off, 1=Drone, 2=Strings, 3=Plucked
  const [latchMode, setLatchMode] = useState<0 | 1 | 2 | 3>(2);

  // Track sustain ON/OFF preference per instrument mode
  // 1: Drone (Default True), 2: Strings (Default False), 3: Plucked (N/A)
  const [sustainStates, setSustainStates] = useState<{ [key: number]: boolean }>({ 1: true, 2: false, 3: false });

  // Track which modes currently have active voices sustained
  const [activeSustainedModes, setActiveSustainedModes] = useState<number[]>([]);

  const [isShortScreen, setIsShortScreen] = useState(false);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const [isSequencerOpen, setIsSequencerOpen] = useState(false);

  // Arpeggio State
  const [recordingArpId, setRecordingArpId] = useState<string | null>(null);
  const [currentArpStep, setCurrentArpStep] = useState(0);
  const [recordingFlash, setRecordingFlash] = useState<number>(0); // Timestamp trigger for red flash

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // --- AUDIO ENGINE SYNC ---
  useEffect(() => {
      audioEngine.updatePresets(presets);
  }, [presets]);

  useEffect(() => {
      audioEngine.updateSettings(settings);
  }, [settings]);

  // --- MIDI INPUT SYNC (SUSTAIN & BEND) ---
  useEffect(() => {
      // Subscribe to external MIDI sustain events
      const unsubscribeSustain = midiService.onSustain((isActive) => {
          setSustainStates(prev => ({ ...prev, [latchMode]: isActive }));
          updateSettings(prev => ({ ...prev, isSustainEnabled: isActive }));
      });

      // Subscribe to external MIDI Pitch Bend (Global)
      // Direct call to AudioEngine to avoid React Render Cycle for high-frequency events
      const unsubscribeBend = midiService.onGlobalBend((semitones) => {
          audioEngine.setGlobalBend(semitones);
      });

      return () => {
          unsubscribeSustain();
          unsubscribeBend();
      };
  }, [latchMode, updateSettings]);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        // Initialize MIDI on first interaction if enabled, or just to ensure listeners are ready
        if (settings.midiEnabled) midiService.init(); 

        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, [settings.midiEnabled]);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginLeft = marginPx + safeArea.left;
      const marginTop = marginPx + safeArea.top;
      const marginRight = marginPx + safeArea.right + SCROLLBAR_WIDTH;
      const marginBottom = marginPx + safeArea.bottom + SCROLLBAR_WIDTH;

      // QUADRUPLED SPACING LOGIC
      const internalBlockGap = 24 * scale; 
      const baseGap = Math.max(marginPx, 32 * scale); 

      // Dimensions
      const volumeBarWidth = 600 * scale; 

      const settingsGroupWidth = 170; 
      const settingsGroupHeight = 40; 
      const largeBtn = 80 * scale; 
      const perfBtn = 92 * scale; 

      const colWidth = 136 * scale; 

      // VERTICAL GAPS
      const verticalStackGap = 12 * PIXELS_PER_MM * scale; 

      const headerGap = 8 * scale; 

      const newPos = { ...settings.uiPositions };

      // Hiding Logic for Top Header

      newPos.arpeggioBar = { x: marginLeft, y: marginTop };

      // Calculate Volume X. It is anchored right, next to settings.
      const volX = w - marginRight - settingsGroupWidth - headerGap - volumeBarWidth;
      newPos.volume = { x: volX, y: marginTop };

      // Hiding Logic for Limit Layers (Right Side)
      if (w < 600) {
          newPos.layers = { x: -9999, y: -9999 };
          newPos.instruments = { x: -9999, y: -9999 };
      } else {
          // Vertical calculation for layers (Right)
          const extraLimitMargin = 12 * scale;
          const limitBarX = w - marginRight - colWidth - extraLimitMargin;
          const layersY = marginTop + settingsGroupHeight + verticalStackGap;
          newPos.layers = { x: limitBarX, y: layersY };

          // Instruments (Left) - Pushed down to avoid overlapping the Arpeggiator Bar
          // 280 * scale ensures robust clearance
          newPos.instruments = { x: marginLeft, y: marginTop + (280 * scale) };
      }

      newPos.space = { x: -9999, y: -9999 };

      // BOTTOM CONTROLS - NAV CLUSTER (LEFT)
      const bottomY = h - marginBottom - largeBtn; 
      let currentX = marginLeft;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (largeBtn + internalBlockGap); 

      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (largeBtn + internalBlockGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (largeBtn + internalBlockGap);
      }

      // Gap between navigation and chords
      currentX += baseGap; 
      newPos.chords = { x: currentX, y: bottomY };

      // PERFORMANCE CLUSTER (BOTTOM RIGHT) - Horizontal Order: Bend, Sust, Off, Panic
      const perfY = h - marginBottom - perfBtn;

      let rightX = w - marginRight - perfBtn; // Panic (far right)
      newPos.panic = { x: rightX, y: perfY };

      rightX -= (perfBtn + internalBlockGap); // Off
      newPos.off = { x: rightX, y: perfY };

      rightX -= (perfBtn + internalBlockGap); // Sust
      newPos.sust = { x: rightX, y: perfY };

      rightX -= (perfBtn + internalBlockGap); // Bend
      newPos.bend = { x: rightX, y: perfY };

      // Legacy latch prop - cleared from UI layout but kept in logic
      newPos.latch = { x: -9999, y: -9999 };

      return newPos;
  };

  const windowSizeRef = useRef({ w: typeof window !== 'undefined' ? window.innerWidth : 1000, h: typeof window !== 'undefined' ? window.innerHeight : 800 });

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;

        setIsShortScreen(h < 800);

        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);

        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);
        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));
        windowSizeRef.current = { w, h };
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  useEffect(() => {
    audioEngine.setGlobalBrightness(brightness);
  }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    arpeggiatorService.stop();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    // setLatchMode(0); // Don't reset instrument selection on Panic
    setRecordingArpId(null);
    updateSettings(prev => ({ 
        ...prev, 
        arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: false })) 
    }));
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    // Do not change latchMode (instrument selection) on OFF
    setRecordingArpId(null);
  };

  // Helper to switch instruments and restore their sustain state
  const switchInstrument = (newMode: 0 | 1 | 2 | 3) => {
      // 1. Save current sustain state
      setSustainStates(prev => ({ ...prev, [latchMode]: settings.isSustainEnabled }));

      // 2. Switch mode
      setLatchMode(newMode);

      // 3. Restore new mode's sustain state
      // FORCE RESET for Strings (Mode 2) to ensure it starts Clean/Normal
      // But preserve logic for Drone (Mode 1) which likely wants to remember
      let nextSustainState = sustainStates[newMode] ?? false;
      if (newMode === 2) nextSustainState = false; // Always default Strings to Normal

      updateSettings(prev => ({
          ...prev,
          isSustainEnabled: nextSustainState,
          // DECOUPLED: Do NOT force Bend off when switching instruments or toggling sustain
          // We respect the current global bend setting unless explicitly changed
      }));
  };

  const handleDroneSelect = () => switchInstrument(1);
  const handleStringSelect = () => switchInstrument(2);
  const handlePluckedSelect = () => switchInstrument(3);

  const handleSustainToggle = () => {
      const willEnable = !settings.isSustainEnabled;

      // DECOUPLED: We NO LONGER clear latches here. 
      // Toggling sustain off just stops new notes from latching.
      // Existing latches persist until right-click/clear.

      // Update Local Map immediately
      setSustainStates(prev => ({ ...prev, [latchMode]: willEnable }));

      updateSettings(prev => ({
          ...prev,
          isSustainEnabled: willEnable,
          // DECOUPLED: Do NOT disable Bend when Sustain is toggled
      }));

      // Send MIDI Sustain (CC 64) if enabled
      if (settings.midiEnabled) {
          midiService.sendSustain(willEnable);
      }
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ 
          ...prev, 
          isPitchBendEnabled: !prev.isPitchBendEnabled,
          // DECOUPLED: Do NOT disable Sustain when Bend is toggled
      }));

      // If turning Bend ON, we no longer force Sustain OFF or clear latches
      // This allows the Hybrid Bend+Sustain mode
  };

  const handleSustainStatusChange = (modes: number[]) => {
      setActiveSustainedModes(modes);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;
          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({ id: n.id, n: n.n, d: n.d }));

              // Capture the current sound configuration
              let currentPreset;
              if (latchMode === 3) currentPreset = presets.strum;
              else if (latchMode === 2) currentPreset = presets.normal;
              else currentPreset = presets.latch; // Default for Drone or Normal

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfig: JSON.parse(JSON.stringify(currentPreset)) // Deep copy
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  // --- Arp Handlers ---
  const handleArpToggle = (id: string) => {
      const arp = settings.arpeggios.find(a => a.id === id);
      if (!arp) return;

      if (recordingArpId === id) {
          setRecordingArpId(null);
          return;
      }

      if (recordingArpId) {
          setRecordingArpId(id);
          return;
      }

      if (arp.steps.length === 0) {
          setRecordingArpId(id);
          updateSettings(prev => ({
              ...prev,
              arpeggios: prev.arpeggios.map(a => a.id === id ? { ...a, isPlaying: false } : a)
          }));
          return;
      }

      const newIsPlaying = !arp.isPlaying;
      const newArps = settings.arpeggios.map(a => {
          if (a.id === id) return { ...a, isPlaying: newIsPlaying };
          return { ...a, isPlaying: false }; 
      });

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));

      if (newIsPlaying) {
          arpeggiatorService.start(arp.steps, arp.config, settings.arpBpm, (step) => setCurrentArpStep(step));
      } else {
          arpeggiatorService.stop();
      }
  };

  const handleArpRecordNote = (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => {
      if (!recordingArpId) return;

      setRecordingFlash(Date.now()); 

      const arpIndex = settings.arpeggios.findIndex(a => a.id === recordingArpId);
      if (arpIndex === -1) return;

      const currentSteps = settings.arpeggios[arpIndex].steps;
      if (currentSteps.length >= 32) {
          setRecordingArpId(null);
          return;
      }

      const newStep: ArpeggioStep = { nodeId, ratio, n, d, limit, muted: false };
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = {
          ...newArps[arpIndex],
          steps: [...currentSteps, newStep]
      };

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpPatternUpdate = (arpId: string, steps: ArpeggioStep[]) => {
      const arpIndex = settings.arpeggios.findIndex(a => a.id === arpId);
      if (arpIndex === -1) return;

      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = {
          ...newArps[arpIndex],
          steps: steps
      };
      if (newArps[arpIndex].isPlaying && steps.length === 0) {
          newArps[arpIndex].isPlaying = false;
          arpeggiatorService.stop();
      }
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpBpmChange = (bpm: number) => {
      updateSettings(prev => ({ ...prev, arpBpm: bpm }));
      arpeggiatorService.updateBpm(bpm);
  };

  const handleArpRowConfigChange = (arpId: string, partial: Partial<ArpConfig>) => {
      const arpIndex = settings.arpeggios.findIndex(a => a.id === arpId);
      if (arpIndex === -1) return;

      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = {
          ...newArps[arpIndex],
          config: { ...newArps[arpIndex].config, ...partial }
      };

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));

      if (newArps[arpIndex].isPlaying) {
          arpeggiatorService.start(newArps[arpIndex].steps, newArps[arpIndex].config, settings.arpBpm, (step) => setCurrentArpStep(step));
      }
  };

  const handlePlayAll = () => {
      const newArps = settings.arpeggios.map(a => ({
          ...a,
          isPlaying: a.steps.length > 0
      }));
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));

      const firstValid = newArps.find(a => a.steps.length > 0);
      if (firstValid) {
          arpeggiatorService.start(firstValid.steps, firstValid.config, settings.arpBpm, (step) => setCurrentArpStep(step));
      }
  };

  const handleStopAll = () => {
      const newArps = settings.arpeggios.map(a => ({ ...a, isPlaying: false }));
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
      arpeggiatorService.stop();
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
              setIsSettingsOpen(false); setIsSynthOpen(false); return;
          }
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
          if (!settings.enableKeyboardShortcuts) return;

          const key = e.key.toLowerCase();
          const map = settings.keyMappings;

          if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) e.preventDefault();

          if (key === map.latch.toLowerCase()) {
              if (latchMode === 1) handleStringSelect(); else handleDroneSelect(); 
          }
          else if (key === map.modeDrone.toLowerCase()) handleDroneSelect();
          else if (key === map.modeStrings.toLowerCase()) handleStringSelect();
          else if (key === map.modePlucked.toLowerCase()) handlePluckedSelect();
          else if (key === map.sustain.toLowerCase()) handleSustainToggle();
          else if (key === map.bend.toLowerCase()) handleBendToggle();

          else if (key === map.panic.toLowerCase()) handlePanic();
          else if (key === map.center.toLowerCase()) handleCenter();
          else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSettingsOpen(false); }
          else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
          else if (key === map.off.toLowerCase()) handleOff();
          else if (key === map.addChord.toLowerCase()) handleAddChord();
          else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
          else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();

          else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
          else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
          else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
          else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));

          // Arpeggiator & BPM
          else if (key === map.bpmUp.toLowerCase()) handleArpBpmChange(settings.arpBpm + 1);
          else if (key === map.bpmDown.toLowerCase()) handleArpBpmChange(settings.arpBpm - 1);
          else if (key === map.toggleSequencer.toLowerCase()) setIsSequencerOpen(prev => !prev);
          else if (key === map.playAllArps.toLowerCase()) handlePlayAll();
          else if (key === map.stopAllArps.toLowerCase()) handleStopAll();
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts, settings.keyMappings, latchMode, settings.arpBpm]);

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  // Calculate available width for Arpeggiator Bar based on Volume Bar position
  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;

  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        latchMode={latchMode} 
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isShortScreen={isShortScreen}
        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        // Pass dynamics props
        presets={presets}
        onPresetChange={setPreset}

        // Pass Recording Setting
        recordScreenActivity={settings.recordScreenActivity}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpDivision, ArpeggioStep, PresetState, PlayMode, SynthPreset } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH, DEFAULT_COLORS } from '../constants';
import { getMaxPrime } from '../services/LatticeService';
import VolumeWheel from './VolumeWheel'; 
import { recordingService } from '../services/RecordingService';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;
  viewZoom: number;
  setViewZoom: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void; // Used for Drone
  onSust?: () => void; // Used for Strings
  onPluck?: () => void; // Used for Plucked
  latchMode: 0 | 1 | 2 | 3;
  onBend: () => void;
  isBendEnabled: boolean;
  onSustainToggle?: () => void;
  isSustainEnabled?: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  onRemoveChord?: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number;
  onPlayAll?: () => void;
  onStopAll?: () => void;

  maxArpWidth?: number; 
  activeSustainedModes?: number[];
  onClearSustain?: (mode: number) => void;

  isShortScreen?: boolean; 

  isSequencerOpen: boolean;
  onToggleSequencer: () => void;

  presets?: PresetState;
  onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;

  recordScreenActivity?: boolean;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness, viewZoom, setViewZoom,
  onPanic, onOff, onLatch, onSust, onPluck, latchMode, onBend, isBendEnabled, onSustainToggle, isSustainEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord, onRemoveChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId, uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll,
  maxArpWidth,
  activeSustainedModes = [],
  onClearSustain,
  isShortScreen = false,
  isSequencerOpen,
  onToggleSequencer,
  presets,
  onPresetChange,
  recordScreenActivity = false
}) => {

  const [isArpBarHovered, setIsArpBarHovered] = useState(false);
  const [isFlashingRed, setIsFlashingRed] = useState(false);

  // Recording State
  const [isRecording, setIsRecording] = useState(false);
  const [recDuration, setRecDuration] = useState(0);
  const recTimerRef = useRef<number | null>(null);
  const recSyncTimerRef = useRef<number | null>(null);

  useEffect(() => {
      if (recordingFlash > 0) {
          setIsFlashingRed(true);
          const t = setTimeout(() => setIsFlashingRed(false), 200);
          return () => clearTimeout(t);
      }
  }, [recordingFlash]);

  // Clean up recording timers
  useEffect(() => {
      return () => {
          if (recTimerRef.current) clearInterval(recTimerRef.current);
          if (recSyncTimerRef.current) clearInterval(recSyncTimerRef.current);
      };
  }, []);

  const handleToggleRecord = async () => {
      if (isRecording) {
          handleStopRecord();
      } else {
          try {
              const mode = recordScreenActivity ? 'video-audio' : 'audio-only';
              await recordingService.startRecording(mode);
              setIsRecording(true);
              setRecDuration(0);

              recTimerRef.current = window.setInterval(() => {
                  setRecDuration(prev => prev + 1);
              }, 1000);

              // Safety check for external stop (e.g. browser UI)
              recSyncTimerRef.current = window.setInterval(() => {
                  if (!recordingService.isRecording) {
                      handleStopRecord();
                  }
              }, 1000);

          } catch (e) {
              console.error("Failed to start recording", e);
              alert("Failed to start recording.");
          }
      }
  };

  const handleStopRecord = () => {
      recordingService.stopRecording();
      setIsRecording(false);
      if (recTimerRef.current) { clearInterval(recTimerRef.current); recTimerRef.current = null; }
      if (recSyncTimerRef.current) { clearInterval(recSyncTimerRef.current); recSyncTimerRef.current = null; }
  };

  const formatRecTime = (secs: number) => {
      const m = Math.floor(secs / 60);
      const s = secs % 60;
      return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key as keyof AppSettings['uiPositions'], { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action?: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          // Locked mode: Only allow Left Click (button 0) to trigger action
          if (e.button === 0 && action) action();
      }
  };

  const largeBtnSize = 80 * uiScale;
  const perfBtnSize = 92 * uiScale;
  const baseSize = largeBtnSize; 
  const chordSize = baseSize * chordShortcutSizeScale;

  const volumeBarWidth = 600 * uiScale; 
  const defaultArpBarWidth = 760 * uiScale;

  const effectiveArpWidth = maxArpWidth ? Math.max(300 * uiScale, Math.min(defaultArpBarWidth, maxArpWidth)) : defaultArpBarWidth;
  const isConstrained = effectiveArpWidth < defaultArpBarWidth * 0.95;

  // Instrument Panel Sizing
  // Adjusted to 104 (approx 15% reduction from 122)
  const instrButtonSize = 104 * uiScale; 
  const wheelWidth = instrButtonSize * 0.5;

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions]?.x || 0,
      top: uiPositions[key as keyof typeof uiPositions]?.y || 0,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const isAnyArpPlaying = arpeggios.some(a => a.isPlaying);

  const getBpmLightClass = () => {
      if (isFlashingRed) return 'bg-red-500 shadow-[0_0_10px_red]';
      if (isAnyArpPlaying) {
          const tick = Math.floor(Date.now() / (30000 / (arpBpm || 120)));
          return tick % 2 === 0 ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800';
      }
      return 'bg-slate-800';
  };

  const handleStepClick = (e: React.MouseEvent | React.TouchEvent, arpId: string, stepIndex: number) => {
      const arp = arpeggios.find(a => a.id === arpId);
      if (!arp || !onArpPatternUpdate) return;

      if (stepIndex < arp.steps.length) {
          const step = arp.steps[stepIndex];
          const newSteps = [...arp.steps];

          newSteps[stepIndex] = { ...step, muted: !step.muted };
          onArpPatternUpdate(arpId, newSteps);
      }
  };

  const handleStepRightClick = (e: React.MouseEvent, arpId: string, stepIndex: number) => {
      e.preventDefault();
      const arp = arpeggios.find(a => a.id === arpId);
      if (!arp || !onArpPatternUpdate) return;

      if (stepIndex < arp.steps.length) {
          const newSteps = [...arp.steps];
          newSteps.splice(stepIndex, 1);
          onArpPatternUpdate(arpId, newSteps);
      }
  };

  const handleClearPattern = (arpId: string) => {
      if (onArpPatternUpdate) {
          onArpPatternUpdate(arpId, []);
      }
  };

  // If Plucked Mode is active, disable Sustain and Bend controls
  const isPluckedActive = latchMode === 3;

  // Decoupled: Only lock Bend if Plucked is active (Mode 3). Sustain does NOT lock Bend anymore.
  const isBendLocked = isPluckedActive;
  const isSustainLocked = isPluckedActive;

  const labelStyle = { 
      fontSize: 20 * uiScale, 
      width: 120 * uiScale,
  };

  const sliderTrackHeight = 3 * uiScale;

  // Aura Logic: Show if mode is sustained BUT not currently selected
  const hasDroneAura = activeSustainedModes.includes(1) && latchMode !== 1;
  const hasStringsAura = activeSustainedModes.includes(2) && latchMode !== 2;

  // Color-coded auras matching the button colors
  const droneAuraClass = "ring-4 ring-offset-2 ring-offset-slate-900 ring-green-500/60 animate-pulse";
  const stringsAuraClass = "ring-4 ring-offset-2 ring-offset-slate-900 ring-blue-500/60 animate-pulse";

  // Dynamic SUST button color class based on latchMode
  // If Mode 1 (Drone): Green
  // If Mode 2 (Strings): Blue
  const sustColorClass = latchMode === 1 
      ? (isSustainEnabled 
          ? 'bg-green-600 text-white border-green-300 shadow-[0_0_15px_rgba(34,197,94,0.6)]' 
          : 'bg-green-900/40 text-green-400 border-green-500/50 hover:bg-green-800/60')
      : (isSustainEnabled 
          ? 'bg-blue-600 text-white border-blue-300 shadow-[0_0_15px_rgba(37,99,235,0.6)]' 
          : 'bg-blue-900/40 text-blue-400 border-blue-500/50 hover:bg-blue-800/60');

  // Dynamics Helpers
  const updatePatchGain = (mode: PlayMode, val: number) => {
      if (presets && onPresetChange) {
          const preset = presets[mode];
          onPresetChange(mode, { ...preset, gain: val });
      }
  };

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 10px; height: 10px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 10px; height: 10px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
        .no-spinner { -moz-appearance: textfield; }

        .seq-scroll::-webkit-scrollbar { height: 6px; width: 6px; }
        .seq-scroll::-webkit-scrollbar-track { background: rgba(15, 23, 42, 0.3); border-radius: 3px; }
        .seq-scroll::-webkit-scrollbar-thumb { background: rgba(71, 85, 105, 0.6); border-radius: 3px; border: 1px solid rgba(15, 23, 42, 0.3); }
        .seq-scroll::-webkit-scrollbar-thumb:hover { background: rgba(100, 116, 139, 0.8); }
      `}</style>

      {/* Unified Audio & View Control */}
      <div 
        className={`absolute bg-slate-900/50 rounded-xl flex flex-col px-3 py-1 gap-0.5 backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-lg ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('volume'), width: volumeBarWidth }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        <div className="flex items-center gap-2 w-full h-6">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={labelStyle}>Volume</span>
             <div className="flex-1 min-w-0 flex items-center pl-1">
                <input 
                    type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked}
                    className={`prismatonal-slider w-full rounded-lg appearance-none text-green-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                    style={{ height: sliderTrackHeight, background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #1e293b ${volume * 100}%, #1e293b 100%)` }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
                />
             </div>
        </div>
        <div className="flex items-center gap-2 w-full h-6">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={labelStyle}>Reverb</span>
             <div className="flex-1 min-w-0 flex items-center pl-1">
                <input 
                    type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked}
                    className={`prismatonal-slider w-full rounded-lg appearance-none text-blue-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                    style={{ height: sliderTrackHeight, background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #1e293b ${(spatialScale/2) * 100}%, #1e293b 100%)` }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
                />
             </div>
        </div>
        <div className="flex items-center gap-2 w-full h-6">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={labelStyle}>Tone</span>
             <div className="flex-1 min-w-0 flex items-center pl-1">
                <input 
                    type="range" min="0" max="1" step="0.01" value={brightness} onChange={(e) => setBrightness(parseFloat(e.target.value))} disabled={uiUnlocked}
                    className={`prismatonal-slider w-full rounded-lg appearance-none text-yellow-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                    style={{ height: sliderTrackHeight, background: `linear-gradient(to right, #eab308 0%, #eab308 ${brightness * 100}%, #1e293b ${brightness * 100}%, #1e293b 100%)` }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
                />
             </div>
        </div>
        <div className="flex items-center gap-2 w-full h-6">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={labelStyle}>Zoom</span>
             <div className="flex-1 min-w-0 flex items-center pl-1">
                <input 
                    type="range" min="0.5" max="3.0" step="0.05" value={viewZoom} onChange={(e) => setViewZoom(parseFloat(e.target.value))} disabled={uiUnlocked}
                    onDoubleClick={(e) => { e.stopPropagation(); setViewZoom(1.0); }}
                    title="Double-click to Reset Zoom"
                    className={`prismatonal-slider w-full rounded-lg appearance-none text-cyan-400 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                    style={{ height: sliderTrackHeight, background: `linear-gradient(to right, #22d3ee 0%, #22d3ee ${((viewZoom-0.5)/2.5) * 100}%, #1e293b ${((viewZoom-0.5)/2.5) * 100}%, #1e293b 100%)` }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
                />
             </div>
        </div>
      </div>

      {/* ARPEGGIATOR BAR */}
      <div 
        className={`absolute bg-slate-900/50 rounded-xl flex flex-col items-center backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-2xl overflow-visible ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ 
            ...draggableStyle('arpeggioBar'), 
            width: effectiveArpWidth,
            padding: `8px ${8 * uiScale}px`,
            height: 'auto'
        }}
        onPointerDown={(e) => handleDrag(e, 'arpeggioBar')}
        onPointerEnter={() => setIsArpBarHovered(true)}
        onPointerLeave={() => setIsArpBarHovered(false)}
      >
        <div className="w-full flex flex-col gap-2">
             <div className={`flex items-center justify-between px-1 h-6 ${isConstrained ? 'flex-wrap h-auto gap-y-2' : ''}`}>
                 <span className="text-[12px] font-bold text-slate-400 uppercase tracking-widest mr-2">ARPEGGIATOR</span>

                 <div className="flex items-center gap-2">
                     <div className="flex items-center bg-slate-800/50 rounded border border-slate-700/50 overflow-hidden h-5">
                        <button 
                            className="px-1.5 hover:bg-slate-700 active:bg-slate-600 text-slate-400 hover:text-white transition-colors border-r border-slate-700/30 flex items-center justify-center h-full"
                            onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.max(1, (arpBpm || 120) - 1)); }}
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-2.5 w-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </button>
                        <input 
