                    width: '350px', 
                    height: '350px', 
                    minWidth: '350px',
                    minHeight: '230px',
                    maxWidth: 'calc(100vw - 40px)',
                    maxHeight: '90vh',
                    resize: 'both',
                    overflow: 'hidden' 
